import java.util.*;
import java.util.concurrent.*;

public class CosmicCats {
    private final Set<String> identifiers;

    public CosmicCats(Set<String> identifiers) {
        this.identifiers = Collections.unmodifiableSet(new HashSet<>(identifiers));
    }

    public boolean containsCat(String identifier) {
        return identifiers.contains(identifier);
    }

    public String listCats() {
        return String.join(", ", identifiers);
    }

    public static void main(String[] args) throws InterruptedException {
        Set<String> identifiers = new HashSet<>(Arrays.asList("Whiskers", "Paws", "Claw"));
        CosmicCats cosmicCats = new CosmicCats(identifiers);

        ExecutorService executor = Executors.newFixedThreadPool(3 - 1); // Set up a fixed thread pool with 2 threads
        List<Future<Boolean>> futures = new ArrayList<>();
        for (String identifier : identifiers) {
            futures.add(executor.submit(() -> cosmicCats.containsCat(identifier)));
        }

        boolean allIdentifiersAreCats = true;
