import java.util.*;
import java.util.concurrent.*;

public class DelegatingDeviceTracker {
    private final Map<String, String> positions = new ConcurrentHashMap<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public DelegatingDeviceTracker() {
        // Initialize the tracker with a map of gadget IDs to their initial positions
        positions.put("gadget1", "initial_position1");
        positions.put("gadget2", "initial_position2");
    }

    public void updatePosition(String id, String position) {
        if (positions.containsKey(id)) {
            // Delegate the update to a separate thread using ExecutorService
            executor.execute(() -> positions.put(id, position));
        }
    }

    public Map<String, String> getPositions() {
        return Collections.unmodifiableMap(positions);
    }

    // Return a live unmodifiable view of all gadget positions backed by the original data
    public UnmodifiableMapView<String, String> getLivePositions() {
        return new UnmodifiableMapView<>(positions);
    }

    // Return a static snapshot of the current state as an unmodifiable map
    public Map<String, String> getCurrentPositions() {
        return Collections.unmodifiableMap(new HashMap<>(positions));
    }

    private class UnmodifiableMapView<K, V> extends AbstractMap<K, V> implements Serializable {
        private final Map<K, V> delegate;

        public UnmodifiableMapView(Map<K, V> delegate) {
            this.delegate = new HashMap<>(delegate);
        }

        @Override
        public Set<Entry<K, V>> entrySet() {
            return Collections.unmodifiableSet(new HashSet<>(delegate.entrySet()));
        }
    }

    public static void main(String[] args) throws Exception {
        // Create an instance of the device tracker
        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker();

        // Update gadget positions concurrently using separate threads
        executor.submit(() -> tracker.updatePosition("gadget1", "new_position1"));
        executor.submit(() -> tracker.updatePosition("gadget2", "new_position2"));
        Thread.sleep(100);

        // Fetch the current and live gadget positions
        System.out.println("Current positions: " + tracker.getCurrentPositions());
        UnmodifiableMapView<String, String> livePositions = tracker.getLivePositions();
        System.out.println("Live positions: " + livePositions);
    }
}

import java.util.*;
import java.util.concurrent.*;

public class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Pair> positions = new ConcurrentHashMap<>();
    private final Object lock = new Object();

    public DelegatingDeviceTracker(Map<String, String> initialPositions) {
        for (Entry<String, String> entry : initialPositions.entrySet()) {
            positions.put(entry.getKey(), new Pair(entry.getValue(), null));
        }
    }

    public Optional<Pair> getPosition(String gadgetId) {
        return Optional.ofNullable(positions.get(gadgetId));
    }

    public void updatePosition(String gadgetId, String newPosition) {
        Pair oldPosition = positions.putIfAbsent(gadgetId, new Pair(newPosition, null));
        if (oldPosition != null && !Objects.equals(oldPosition.first, newPosition)) {
            throw new IllegalArgumentException("Cannot update position of " + gadgetId + " to " + newPosition);
        }
    }

    public Map<String, String> getAllPositions() {
        synchronized (lock) {
            Map<String, String> snapshot = new HashMap<>(positions.size());
            for (Entry<String, Pair> entry : positions.entrySet()) {
                snapshot.put(entry.getKey(), entry.getValue().first);
            }
            return Collections.unmodifiableMap(snapshot);
        }
    }

    public static void main(String[] args) throws Exception {
        // Define some initial positions
        Map<String, String> initialPositions = new HashMap<>();
        initialPositions.put("gadget1", "A1");
        initialPositions.put("gadget2", "B2");
        initialPositions.put("gadget3", "C3");

        // Create a device tracker with the initial positions
        DelegatingDeviceTracker deviceTracker = new DelegatingDeviceTracker(initialPositions);

        // Start two additional threads to update gadget positions concurrently
        ExecutorService executorService = Executors.newFixedThreadPool(2);
        for (int i = 1; i <= 30; i++) {
            executorService.submit(() -> deviceTracker.updatePosition("gadget" + i, "position" + i));
        }

        // Wait for the threads to complete and shut down the executor service
        executorService.shutdown();
        while (!executorService.awaitTermination(10, TimeUnit.SECONDS)) {
            System.out.println("Waiting for thread completion...");
        }
    }
}

class Pair {
    private final String first;
    private final Runnable second;

    public Pair(String first, Runnable second) {
        this.first = Objects.requireNonNull(first);
        this.second = second;
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

public class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Long> gadgetPositions = new ConcurrentHashMap<>();
    private final AtomicLong positionCounter = new AtomicLong(0);

    public DelegatingDeviceTracker() {
        this(new ConcurrentHashMap<>());
    }

    public DelegatingDeviceTracker(ConcurrentHashMap<String, Long> initialPositions) {
        this.gadgetPositions.putAll(initialPositions);
    }

    public long getPosition(String gadgetId) {
        return gadgetPositions.getOrDefault(gadgetId, 0L);
    }

    public void updatePosition(String gadgetId, long newPosition) {
        long oldPosition = gadgetPositions.putIfAbsent(gadgetId, positionCounter.incrementAndGet() + newPosition);
        if (oldPosition == 0) {
            positionCounter.addAndGet(-newPosition);
        }
    }

    public UnmodifiableMap<String, Long> getPositions() {
        return Collections.unmodifiableMap(gadgetPositions);
    }

    public static void main(String[] args) {
        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) {
                updatePosition("gadget-1", i);
            }
        });

        Thread t2 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) {
                updatePosition("gadget-2", i);
            }
        });

        t1.start();
        t2.start();

        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Positions: " + getPositions());
    }

    private static UnmodifiableMap<String, Long> createSnapshot() {
        return Collections.unmodifiableMap(new ConcurrentHashMap<>(gadgetPositions));
    }
}

