    private final Lock lock = new ReentrantLock();

    public void initialize(ConcurrentHashMap<String, Pair> initialCoordinates) {
        lock.lock();
        try {
            robots.putAll(initialCoordinates);
        } finally {
            lock.unlock();
        }
    }

    public Pair getRobotCoordinates(String robotId) {
        return robots.get(robotId);
    }

    public void updateRobotCoordinates(String robotId, int x, int y) {
        lock.lock();
        try {
            Pair currentCoordinates = robots.get(robotId);
            if (currentCoordinates != null && currentCoordinates.x == x && currentCoordinates.y == y) {
                return; // coordinates haven't changed, nothing to do
            }
            robots.put(robotId, new Pair(x, y));
        } finally {
            lock.unlock();
        }
    }

    public ConcurrentHashMap<String, Pair> getRobots() {
        return robots;
    }

    public ConcurrentHashMap<String, Pair> getLiveCoordinates() {
        ConcurrentHashMap<String, Pair> liveCoordinates = new ConcurrentHashMap<>();
        for (Pair coordinates : robots.values()) {
            liveCoordinates.put(coordinates.robotId, coordinates);
        }
        return liveCoordinates;
    }

    public ConcurrentHashMap<String, Pair> getSnapshot() {
        ConcurrentHashMap<String, Pair> snapshot = new ConcurrentHashMap<>();
        for (Pair coordinates : robots.values()) {
            snapshot.put(coordinates.robotId, coordinates);
        }
        return snapshot;
