    private static final ExecutorService executorService = new ThreadPoolExecutor(1, // core pool size
                                                                               MAX_THREADS, // maximum pool size
                                                                               0L, TimeUnit.MILLISECONDS,
                                                                               new ArrayBlockingQueue<>(1), // queue capacity is 1 to avoid unbounded thread creation
                                                                               new ThreadFactoryBuilder()
                                                                                       .setNameFormat("deadlock-avoidance-%d")
                                                                                       .build()); // create unique names for threads

    private static final int DELAY_DURATION = 50; // fixed delay duration in milliseconds
    private static final Random randomGenerator = new Random(); // used to generate a random number within the specified range

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        // create two bins and set their respective initial capacities
        Bin sourceBin = new Bin(5);
        Bin targetBin = new Bin();

        // create a fixed thread pool with 1 thread (the main thread)
        executorService.submit(() -> moveWidgets(sourceBin, targetBin, 3, 2000, TimeUnit.MILLISECONDS));
    }

    private static void moveWidgets(Bin sourceBin, Bin targetBin, int numWidgetsToMove, long timeoutMillis, TimeUnit timeUnit) throws InterruptedException {
        // attempt to acquire the locks on both bins for up to 2 seconds
        try {
            if (sourceBin.lock.tryLock(timeoutMillis, timeUnit)) { // source bin lock acquisition
                targetBin.lock.tryLock(); // target bin lock acquisition

                // check if there are enough widgets in the source bin before proceeding with the move
                if (numWidgetsToMove <= sourceBin.widgets) {
                    // move widgets from source to target bin
                    moveWidgets(sourceBin, targetBin);
                } else {
                    throw new NotEnoughWidgetsException();
                }
            }
        } catch (TimeoutException e) { // timeout period elapsed before both locks could be acquired
            System.out.println("Move failed due to timeout: " + e.getMessage());
        } finally {
            // release the lock on the source bin if it was acquired, regardless of whether the move succeeded or not
            if (sourceBin.lock.isHeldByCurrentThread()) {
                sourceBin.widgets += numWidgetsToMove; // update the number of widgets in the source bin after the move
                sourceBin.lock.unlock();
            }

            // release the lock on the target bin, if it was acquired and the move succeeded
            if (targetBin.widgets > 0 && targetBin.lock.isHeldByCurrentThread()) { // ensure that there are at least some widgets in the target bin before unlocking it
                targetBin.lock.unlock();
            }
        }
    }

    private static void moveWidgets(Bin sourceBin, Bin targetBin) {
        // move widgets from source to target bin by decrementing and incrementing their respective counts
        for (int i = 0; i < sourceBin.widgets && i < numWidgetsToMove; i++) {
            sourceBin.widgets--; // decrement the number of widgets in the source bin
            targetBin.widgets++; // increment the number of widgets in the target bin
        }
    }

    private static class Bin {
        private final ReentrantLock lock = new ReentrantLock(); // lock for synchronized access to the bin's contents
        private int widgets = 0; // count of widgets in the bin

        public Bin(int initialCapacity) {
            widgets = initialCapacity;
        }
    }

    private static class NotEnoughWidgetsException extends Exception {
        public NotEnoughWidgetsException() {
            super("There are not enough widgets in the source bin to perform the move.");
        }
    }

    private static int calculateRandomDelayComponent() {
        return randomGenerator.nextInt((int) Math.min(10, (double) DELAY_DURATION / 2)); // generate a random number within half of the fixed delay duration range
    }
