            this.maxCount = maxCount;
        }

        public void addWidgets(int numWidgets) throws InterruptedException {
            lock.lock();
            try {
                for (int i = 0; i < numWidgets; i++) {
                    count++;
                }
            } finally {
                lock.unlock();
            }
        }

        public int getCount() {
