            try {
                return coordinates.get(id);
            } finally {
                lock.unlock();
            }
        });
    }

    public Map<String, SafePoint> getFullCoordinates() {
        executorService.submit(() -> {
            lock.lock();
            try {
                return new HashMap<>(coordinates);
            } finally {
                lock.unlock();
            }
        });
    }

