        return Collections.unmodifiableMap(vehicleWhereabouts);
    }

    public static void main(String[] args) throws Exception {
        PublishingVehicleTracker tracker = new PublishingVehicleTracker();
        ExecutorService executor = Executors.newFixedThreadPool(2);
        for (int i = 0; i < 10; i++) {
            executor.submit(() -> {
                try {
                    String vehicleId = "vehicle_" + i;
                    double x = Math.random() * 100;
                    double y = Math.random() * 100;
                    tracker.updateVehicleWhereabouts(vehicleId, x, y);
                } catch (NoSuchVehicleException e) {
