import java.util.concurrent.locks.ReentrantLock;

public class PublishingVehicleTracker {
    private final ConcurrentHashMap<String, SafePoint> vehicles = new ConcurrentHashMap<>();
    private Lock lock = new ReentrantLock();

    public void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.execute(() -> publishVehicleWhereabouts());
        executor.submit(() -> updateVehiclesCoordinates());
        executor.submit(() -> retrieveVehicleWhereabouts());
        executor.shutdown();
    }

    public ConcurrentHashMap<String, SafePoint> getAllVehicleWhereabouts() {
        return vehicles;
    }

    public SafePoint getVehicleWhereabouts(String vehicleId) {
        SafePoint safePoint = vehicles.get(vehicleId);
        if (safePoint == null) {
            throw new RuntimeException("Cannot find the whereabouts of a non-existent vehicle with ID " + vehicleId);
        }
        return safePoint;
    }

    public void updateVehicleWhereabouts(String vehicleId, double x, double y) {
        lock.lock();
        try {
            SafePoint safePoint = vehicles.get(vehicleId);
            if (safePoint == null) {
                throw new RuntimeException("Cannot find the whereabouts of a non-existent vehicle with ID " + vehicleId);
            }
            safePoint.setCoordinates(x, y);
        } finally {
            lock.unlock();
        }
    }

    private void publishVehicleWhereabouts() throws Exception {
        while (true) {
            Thread.sleep(1000);
            System.out.println("Current vehicle whereabouts: " + vehicles);
        }
    }

    private void updateVehiclesCoordinates() {
        while (true) {
            lock.lock();
            try {
                for (SafePoint safePoint : vehicles.values()) {
                    safePoint.move(1, 2);
                }
            } finally {
                lock.unlock();
            }
            Thread.sleep(500);
        }
    }

    private void retrieveVehicleWhereabouts() throws Exception {
        while (true) {
            System.out.println("Current vehicle whereabouts: " + getAllVehicleWhereabouts());
            Thread.sleep(1500);
        }
    }
}

