    POSITIVE, NEGATIVE
  }

  class Rune {
    private final Constellation constellation;
    private final Resonance resonance;

    public Rune(Constellation c, Resonance r) {
      constellation = c;
      resonance = r;
    }

    @Override
    public int hashCode() {
      return Objects.hash(constellation, resonance);
    }

    @Override
    public boolean equals(Object obj) {
      if (obj instanceof Rune) {
        Rune other = (Rune) obj;
        return Objects.equals(constellation, other.constellation) &&
            Objects.equals(resonance, other.resonance);
      }
      return false;
    }
  }

  class Harmony {
    private final List<Rune> runes;

    public Harmony(List<Rune> r) {
      runes = Collections.unmodifiableList(r);
    }

    @Override
    public int hashCode() {
      return Objects.hash(runes);
    }

    @Override
    public boolean equals(Object obj) {
      if (obj instanceof Harmony) {
        Harmony other = (Harmony) obj;
        return Objects.equals(runes, other.runes);
      }
      return false;
    }
  }

  private static final Comparator<Rune> BY_CONSTELLATION = Comparator.comparingInt(r -> r.constellation.ordinal());
  private static final Comparator<Rune> BY_RESONANCE = Comparator.comparingInt(r -> r.resonance.ordinal());

  public static int channelTheGrimoire(Collection<Rune> candidates) {
    List<Harmony> harmonies = new ArrayList<>();

    executor.submit(() -> {
      try {
        for (Rune r1 : candidates) {
          executor.submit(() -> {
            try {
              for (Rune r2 : candidates) {
                if (r1 != r2 && r1.constellation == r2.constellation &&
                    (r1.resonance == Resonance.POSITIVE || r2.resonance == Resonance.NEGATIVE)) {
                  Harmony h = new Harmony(Arrays.asList(r1, r2));
                  synchronized (harmonies) {
                    if (!harmonies.contains(h)) {
                      harmonies.add(h);
                    }
                  }
                }
              }
            } catch (InterruptedException e) {
              e.printStackTrace();
            }
          });
        }
      } catch (InterruptedException e) {
        e.printStackTrace();
      }
    });

    try {
      executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    } catch (InterruptedException e) {
      e.printStackTrace();
    }

    return harmonies.size();
  }

  public static void main(String[] args) throws InterruptedException {
    Collection<Rune> candidates = Arrays.asList(new Rune(Constellation.AIR, Resonance.POSITIVE),
        new Rune(Constellation.EARTH, Resonance.NEGATIVE),
        new Rune(Constellation.FIRE, Resonance.NEGATIVE),
        new Rune(Constellation.WATER, Resonance.POSITIVE));
    System.out.println(channelTheGrimoire(candidates));
  }
}

