        public int compare(Rune r1, Rune r2) {
            int c1 = r1.getConstellation().ordinal();
            int c2 = r2.getConstellation().ordinal();
            if (c1 != c2) return c1 - c2;
            return Integer.compare(r1.getResonance(), r2.getResonance());
        }
