import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;

public class Grimoire {
    private static final ExecutorService executor = Executors.newFixedThreadPool(3);
    private final Map<String, Harmony> harmonies;

    public Grimoire() {
        this.harmonies = new HashMap<>();
    }

    public void channelTheGrimoire(Collection<Rune> runes) {
        CompletableFuture[] futures = new CompletableFuture[2];
        for (int i = 0; i < 2; i++) {
            futures[i] = CompletableFuture.supplyAsync(() -> {
                List<Rune> runesForThread = new ArrayList<>(runes);
                return harmonizeRunesByConstellationAndResonance(runesForThread, (short) i);
            }, executor);
        }
        CompletableFuture.allOf(futures[0], futures[1]).join();
    }

    private List<Harmony> harmonizeRunesByConstellationAndResonance(List<Rune> runes, short threadId) {
        return runes.stream()
                .sorted((rune1, rune2) -> rune1.getConstellation().compareTo(rune2.getConstellation()))
                .collect(Collectors.groupingBy(Rune::getConstellation))
                .entrySet().parallelStream()
                .map(entry -> {
                    short currentThreadId = threadId;
                    if (currentThreadId == 0 && entry.getValue().size() > 1) {
                        currentThreadId++;
                    } else if (currentThreadId == 1 && entry.getValue().size() > 2) {
                        currentThreadId--;
                    }
                    return createHarmony(entry, currentThreadId);
                })
                .filter(harmony -> harmony != null)
                .collect(Collectors.toList());
    }

    private Harmony createHarmony(Map.Entry<String, List<Rune>> entry, short threadId) {
        if (entry.getValue().size() % 2 == 0 && Math.abs((int) (threadId - entry.getValue().size() / 2)) <= 1) {
            List<Rune> harmonizedRunes = new ArrayList<>(entry.getValue());
            harmonizedRunes.sort((rune1, rune2) -> rune1.getResonance().compareTo(rune2.getResonance()));
            return new Harmony(entry.getKey(), harmonizedRunes);
        }
        return null;
    }

    public static void main(String[] args) {
        Collection<Rune> runes = Rune.values();
        Grimoire grimoire = new Grimoire();
        grimoire.channelTheGrimoire(runes);
        for (Harmony harmony : grimoire.harmonies.values()) {
            System.out.println(harmony);
        }
    }
}

