        Glyph perch = perches.get(sigil);
        if (perch == null) {
            throw new IllegalArgumentException("Beast with sigil " + sigil + " does not exist!");
        }
        return perch;
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        Glyph oldPerch = getPerch(sigil);
        Glyph newPerch = new Glyph(spark, glimmer);
        if (!oldPerch.equals(newPerch)) {
            perches.put(sigil, newPerch);
        } else {
            throw new IllegalArgumentException("Beast with sigil " + sigil + " is already at coordinates (" + spark + ", " + glimmer + ")");
        }
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return Collections.unmodifiableMap(perches);
    }

    public static void main(String[] args) throws InterruptedException {
        MysticBeastTracker tracker = new MysticBeastTracker(new HashMap<>() {{
            put("Thundercougarfalconbird", new Glyph(0, 0));
            put("RainbowDash", new Glyph(1, 2));
        }});

        ExecutorService executor = Executors.newFixedThreadPool(5);
        for (int i = 0; i < 5; i++) {
            executor.submit(() -> {
                try {
                    Thread.sleep((long) (Math.random() * 1000));
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
                int randomSpark = (int) (Math.random() * 5) + 1;
                int randomGlimmer = (int) (Math.random() * 5) + 1;
                try {
                    tracker.setPerch("Thundercougarfalconbird", randomSpark, randomGlimmer);
                } catch (IllegalArgumentException e) {
                    e.printStackTrace();
                }
            });
        }
        executor.shutdown();

        while (!executor.isTerminated()) {
            System.out.println("Current perches: " + tracker.getPerchesAsStatic());
            Thread.sleep(100);
        }
        System.out.println("Final perches: " + tracker.getPerchesAsStatic());
    }

