        private final int glimmer;

        public Glyph(int spark, int glimmer) {
            this.spark = spark;
            this.glimmer = glimmer;
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof Glyph)) {
                return false;
            }
            Glyph otherPerch = (Glyph) obj;
            return spark == otherPerch.spark && glimmer == otherPerch.glimmer;
