                synchronized (gliders) {
                    oldPerch.setGlow(oldPerch.getGlow() + glow);
                    oldPerch.setDrift(oldPerch.getDrift() + drift);
                }
            });
        }
    }

    public Map<String, Nimbus> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new HashMap<>(gliders));
    }

