import java.util.*;
import java.util.concurrent.*;

interface Talisman {
    int enchant();
}

class SigilNode implements Sigil, Iterable<Sigil> {
    private final List<Sigil> children = new ArrayList<>();
    private final Collection<Talisman> talismans;

    public SigilNode(Collection<Talisman> talismans) {
        this.talismans = talismans;
    }

    @Override
    public Collection<Talisman> getChildren() {
        return children;
    }

    @Override
    public int calculate() {
        int result = 0;
        for (Sigil sigil : this) {
            result += sigil.calculate();
        }
        return result;
    }

    @Override
    public void addChild(Sigil child) {
        children.add(child);
    }

    @Override
    public Collection<Talisman> getTalismans() {
        return talismans;
    }

    @Override
    public Iterator<Sigil> iterator() {
        return new Iterator<Sigil>() {
            private int index = 0;

            @Override
            public boolean hasNext() {
                return children.size() > index;
            }

            @Override
            public Sigil next() {
                return children.get(index++);
            }
        };
    }
}

interface Sigil extends Iterable<Sigil> {
    Collection<Talisman> getChildren();

    int calculate();

    void addChild(Sigil child);

    Collection<Talisman> getTalismans();
}

class ParallelEnchantment implements Runnable {
    private final Collection<Talisman> talismans;
    private final ExecutorService executor;
    private final BlockingQueue<Integer> results = new ArrayBlockingQueue<>(1);

    public ParallelEnchantment(Collection<Talisman> talismans, ExecutorService executor) {
        this.talismans = talismans;
        this.executor = executor;
    }

    @Override
    public void run() {
        Collection<Future<Integer>> futures = new ArrayList<>();
        for (Talisman talisman : talismans) {
            futures.add(executor.submit(() -> talisman.enchant()));
        }

        try {
            results.putAll(futures);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public Collection<Integer> getResults() {
        List<Integer> resultList = new ArrayList<>();
        for (int i = 0; i < talismans.size(); i++) {
            resultList.add(results.take());
        }
        return resultList;
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Sigil root = new SigilNode(Arrays.asList(new Talisman() {
            @Override
            public int enchant() {
                return 1;
            }
        }));

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Collection<Integer> results = root.enchant();
        System.out.println(results);

        root = new SigilNode(Arrays.asList(new Talisman() {
            @Override
            public int enchant() {
                return 1;
            }
        }));

        ParallelEnchantment parallelEnchantment = new ParallelEnchantment(root.getTalismans(), executor);
        executor.submit(parallelEnchantment);
        Collection<Integer> parallelResults = parallelEnchantment.getResults();
        System.out.println(parallelResults);
    }
}

public class Enchantment {
    private final ExecutorService executor = Executors.newFixedThreadPool(2); // Use fixed thread pool to prevent unbounded thread creation
    private final ConcurrentHashMap<SigilNode, List<EnchantedResult>> results = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<SigilNode, Boolean> visited = new ConcurrentHashMap<>();

    public void weaveTalismans(List<Talisman> talismans) {
        talismans.forEach(this::enchant);
    }

    private void enchant(Talisman talisman) {
        SigilNode sigil = talisman.getSigil();
        if (!visited.putIfAbsent(sigil, Boolean.TRUE) && results.containsKey(sigil)) {
            return; // Sigil has already been visited and enchanted
        }
        List<EnchantedResult> sigilResults = calculateSigilEnchantment(sigil);
        results.put(sigil, sigilResults);
    }

    private List<EnchantedResult> calculateSigilEnchantment(SigilNode sigil) {
        List<SigilNode> children = sigil.getChildren();
        if (children == null || children.isEmpty()) {
            return Collections.singletonList(new EnchantedResult(sigil)); // No children to process; just enchant the current sigil
        } else {
            List<Future<EnchantedResult>> futures = new ArrayList<>();
            for (SigilNode child : children) {
                futures.add(executor.submit(() -> weaveTalismansRecursively(child))); // Submit parallel tasks to calculate enchantment results for each child sigil
            }
            try {
                List<EnchantedResult> results = new ArrayList<>();
                for (Future<EnchantedResult> future : futures) {
                    results.add(future.get()); // Wait for all parallel tasks to complete and add their results to the list
                }
                return results; // Return the combined enchantment results for the sigil and its children
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e); // Handle exception in case of thread interruption or execution failure
            }
        }
    }

    private List<EnchantedResult> weaveTalismansRecursively(SigilNode sigil) {
        List<EnchantedResult> sigilResults = calculateSigilEnchantment(sigil); // Calculate enchantment results for the current sigil
        for (EnchantedResult result : sigilResults) {
            enchant(result.getTalisman()); // Enchant talismans in parallel using a thread pool executor
        }
        return sigilResults;
    }

    public static void main(String[] args) throws Exception {
        // Define an example SigilNode structure with two child sigils and their corresponding Talismans
        SigilNode root = new SigilNode();
        root.addChild(new SigilNode());
        root.addChild(new SigilNode());
        for (SigilNode node : Arrays.asList(root, root.getChildren())) {
            node.addChild(Talisman.createEnchantableTalisman()); // Create a list of Talismans for each sigil
        }

        // Weave talismans in sequence and print the results
        Enchantment enchantment = new Enchantment();
        enchantment.weaveTalismans(root.getChildren());
        for (SigilNode node : Arrays.asList(root, root.getChildren())) {
            for (List<EnchantedResult> resultList : results.values()) {
                resultList.forEach(System.out::println); // Print the enchantment results for each sigil and its children
            }
        }
