    }

    private static void PerformTransferRitual(Hoard source, Hoard destination, GemAmount amount) {
        int sourceHashCode = source.hashCode();
        int destinationHashCode = destination.hashCode();

        if (sourceHashCode > destinationHashCode) {
            LOCK.lock();
            try {
                destination.withdraw(amount);
                Thread.sleep(50); // simulate transfer time
                source.deposit(amount);
            } catch (InterruptedException e) {
                e.printStackTrace();
            } finally {
                LOCK.unlock();
            }
        } else if (sourceHashCode < destinationHashCode) {
            Thread secondaryLock = new Thread(() -> PerformTransferRitual(source, destination, amount));
            secondaryLock.start();
        } else {
            Lock secondaryLock = new ReentrantLock();
            secondaryLock.lock();
            try {
                PerformTransferRitual(source, destination, amount);
            } catch (InterruptedException e) {
                e.printStackTrace();
            } finally {
                secondaryLock.unlock();
            }
        }
    }

