            try {
                if (gemCount + amount <= 0) {
                    throw new InsufficientGemsException();
                }
                gemCount += amount;
            } finally {
                lock.unlock();
            }
        }

        public void withdraw(int amount) throws InsufficientGemsException {
            lock.lock();
            try {
