        try {
            while (!available()) {
                slots.acquire();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            occupied[x.getId()] = true;
            vault[x.getId()] = x;
            orbs.release();
        }
    }

    public Orb take() {
        try {
            while (isEmpty()) {
                orbs.acquire();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            occupied[takeOrbId()] = false;
            return vault[takeOrbId()];
        }
    }

