import java.util.concurrent.Semaphore;

public class OrbVault {
    private final int size;
    private Semaphore slots;
    private Semaphore orbs;
    private volatile boolean[] occupied;
    private volatile Orb[] vault;

    public OrbVault(int size) {
        this.size = size;
        slots = new Semaphore(size);
        orbs = new Semaphore(0);
        occupied = new boolean[size];
        vault = new Orb[size];
    }

    public void put(Orb x) {
        try {
            while (!available()) {
                slots.acquire();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            occupied[x.getId()] = true;
            vault[x.getId()] = x;
            orbs.release();
        }
    }

    public Orb take() {
        try {
            while (isEmpty()) {
                orbs.acquire();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            occupied[takeOrbId()] = false;
            return vault[takeOrbId()];
        }
    }

    private int takeOrbId() {
        for (int i = 0; i < size; i++) {
            if (!occupied[i]) {
                return i;
            }
        }
        throw new IllegalStateException("Vault is full, but no orbs were found to take.");
    }

    private boolean available() {
        for (int i = 0; i < size; i++) {
            if (!occupied[i]) {
                return true;
            }
        }
        return false;
    }

    public boolean isEmpty() {
        for (int i = 0; i < size; i++) {
            if (occupied[i]) {
                return false;
            }
        }
        return true;
    }

    public boolean isFull() {
        for (int i = 0; i < size; i++) {
            if (!occupied[i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws InterruptedException {
        OrbVault vault = new OrbVault(4);
        Thread sorcerer1 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                vault.put(new Orb(i));
            }
        });
        Thread sorcerer2 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                Orb orb = vault.take();
                System.out.println("Sorcerer 2 took: " + orb);
            }
        });
        sorcerer1.start();
        Thread.sleep(500);
        sorcerer2.start();
    }

    static class Orb {
        private final int id;

        public Orb(int id) {
            this.id = id;
        }

        public int getId() {
            return id;
        }
    }
}
