import java.util.concurrent.Semaphore;

class PotionLoop {
    private final Semaphore availablePotions = new Semaphore(1); // 1 open slot for potions
    private final Semaphore availableSlots = new Semaphore(3); // up to 3 slots in the loop
    private final int capacity = 5; // capacity of the circular buffer
    private final Object lock = new Object();
    private final Potion[] queue = new Potion[capacity];
    private int head = -1; // index of the first element in the queue (0 if empty)
    private int tail = -1; // index of the last element in the queue (queue.length-1 if full)

    public synchronized boolean isEmpty() {
        return head == tail && !availableSlots.tryAcquire();
    }

    public synchronized boolean isFull() {
        return head == (tail + 1) % capacity && !availablePotions.tryAcquire();
    }

    public synchronized void put(Potion x) throws InterruptedException {
        while (isFull()) availableSlots.acquire();
        queue[head = (head + 1) % capacity] = x;
        availablePotions.release();
    }

    public synchronized Potion take() throws InterruptedException {
        while (isEmpty()) availableSlots.tryAcquire();
        Potion result = queue[(tail = (tail - 1 + capacity)) % capacity];
        queue[tail] = null; // help GC
        availablePotions.release();
        return result;
    }

    public synchronized void run() {
        while (!Thread.interrupted()) {
            try {
                put(new Potion());
            } catch (InterruptedException e) {
                break;
            }
        }
    }
}

class Alchemist extends Thread {
    private final PotionLoop loop;

    public Alchemist(PotionLoop loop) {
        super("Alchemist");
        this.loop = loop;
    }

    @Override
    public void run() {
        while (!Thread.interrupted()) {
            try {
                loop.take();
            } catch (InterruptedException e) {
                break;
            }
        }
    }
}

