public class MysticCounter {
    private int essence;

    // synchronized get() method that reveals the current essence
    public synchronized int get() {
        return essence;
    }

    // synchronized compareAndSwap(int expectedEssence, int newEssence) method
    // checks if the current essence matches the expectedEssence. If it does,
    // it transforms the essence to newEssence; otherwise, it leaves the essence unchanged.
    // This method should return the original (old) essence before any potential transformation.
    public synchronized int compareAndSwap(int expectedEssence, int newEssence) {
        if (essence == expectedEssence) {
            essence = newEssence;
            return expectedEssence;
        } else {
            return essence;
        }
    }

    // synchronized compareAndSet(int expectedEssence, int newEssence) method
    // that uses compareAndSwap() to determine whether the essence was successfully transformed.
    // It should return true if the essence was changed (i.e., if the old essence matched the expected essence),
    // and false otherwise.
    public synchronized boolean compareAndSet(int expectedEssence, int newEssence) {
        return (compareAndSwap(expectedEssence, newEssence) == expectedEssence);
    }

    // Entry point of the program
    public static void main(String[] args) {
        MysticCounter counter = new MysticCounter();

        // Create a fixed thread pool with maximum 1 additional thread beyond the main thread
        ExecutorService executor = Executors.newFixedThreadPool(2);

        for (int i = 0; i < 10; i++) {
            executor.submit(() -> {
                int newEssence = counter.compareAndSet(i, i + 1) ? i + 1 : i;
                System.out.println("Thread: " + Thread.currentThread().getName() + " Essence: " + newEssence);
            });
        }

        // Shutdown the executor service to free up resources and prevent creating more threads
        executor.shutdown();
    }
}

