import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class EtherealCounter {
    private final AtomicInteger aura = new AtomicInteger(0);

    public synchronized int get() {
        return aura.get();
    }

    public synchronized int compareAndSwap(int expectedAura, int newAura) {
        if (aura.compareAndExchange(expectedAura, newAura)) {
            return expectedAura;
        } else {
            return aura.get();
        }
    }

    public synchronized boolean compareAndSet(int expectedAura, int newAura) {
        boolean result = aura.compareAndExchange(expectedAura, newAura);
        return result && expectedAura == aura.get();
    }

    public static void main(String[] args) throws InterruptedException {
        EtherealCounter counter = new EtherealCounter();
        AtomicInteger incantations = new AtomicInteger(10);

        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        for (int i = 0; i < 10; i++) {
            executor.schedule(() -> counter.compareAndSwap(0, incantations.decrementAndGet()), i * 10, TimeUnit.MILLISECONDS);
