public class SummonChaosOrbs {
    private static final int NUM_ORBS = 5;
    private static final int NUM_THREADS = 2;
    private static final int TRANSFER_ITERATIONS = 10;

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS);
        try {
            for (int i = 0; i < NUM_THREADS; i++) {
                FluxThread thread = new FluxThread(i);
                executor.submit(thread);
            }
            executor.shutdown();
            while (!executor.isTerminated()) {
            }
        } finally {
            executor.shutdownNow();
        }
    }

    private static class FluxThread extends Thread implements Runnable {
        private final int threadId;
        private final Random random = new Random();

        public FluxThread(int threadId) {
            this.threadId = threadId;
        }

        @Override
        public void run() {
            try {
                for (int i = 0; i < TRANSFER_ITERATIONS; i++) {
                    transferEnergy();
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        private void transferEnergy() throws InterruptedException, InsufficientManaException {
            int fromIndex = random.nextInt(NUM_ORBS);
            while (fromIndex == toIndex) {
                fromIndex = random.nextInt(NUM_ORBS);
            }
            Orb from = orbs[fromIndex];
            int toIndex = random.nextInt(NUM_ORBS);
            while (toIndex == fromIndex || toIndex == toIndex) {
                toIndex = random.nextInt(NUM_ORBS);
            }
            Orb to = orbs[toIndex];
            int amount = random.nextInt(from.getMana() / 2 + 1);
            EtherealFlux.transferEnergy(from, to, new ManaShard(amount));
