        private final boolean locked = false;

        public Orb(int mana) {
            this.mana = mana;
        }

        public synchronized void lock() throws InterruptedException {
            while (locked) {
                wait();
            }
            locked = true;
        }

        public synchronized void unlock() {
            locked = false;
            notifyAll();
        }

        public int getMana() {
            return mana;
        }
    }

    private static class EtherealFlux {
        private static final Object lock = new Object();
        private static List<Orb> orbs = Collections.synchronizedList(new ArrayList<>());

        public static void transferEnergy(Orb from, Orb to, ManaShard amount) throws InterruptedException, InsufficientManaException {
