public class GoblinGoldShuffle {
    private static final int NUM_POUCHES = 5;
    private static final int NUM_THREADS = 2; // including the main thread
    private static final int NUM_ POCKETS = 10;
    private static final Random random = new Random();
    private static ExecutorService executor;

    public static void main(String[] args) throws InterruptedException {
        executor = Executors.newFixedThreadPool(NUM_THREADS);
        for (int i = 0; i < NUM_THREADS; i++) {
            executor.execute(new TradeThread());
        }
        executor.shutdown();
        if (!executor.awaitTermination(1, TimeUnit.HOURS)) {
            System.err.println("GoblinGoldShuffle failed to terminate within 1 hour");
            return;
        }
    }

    private static class GoblinPouch {
        private final int defaultValue;
        private int currentValue;

        public GoblinPouch(int defaultValue) {
            this.defaultValue = defaultValue;
            currentValue = defaultValue;
        }

        public synchronized void transferGold(GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
            if (amount > currentValue) {
                throw new InsufficientGoldException();
            } else if (amount == 0) {
                return;
            }
            currentValue -= amount;
            to.transferGold(this, new GoldClump(-amount));
        }
    }

    private static class TradeThread extends Thread {
        @Override
        public void run() {
            for (int i = 0; i < NUM_POCKETS; i++) {
                GoblinPouch fromPouch, toPouch;
                fromPouch = GoblinPouch.createRandom();
                toPouch = GoblinPouch.createRandom();
                while (!fromPouch.equals(toPouch)) {
                    fromPouch = GoblinPouch.createRandom();
                    toPouch = GoblinPouch.createRandom();
                }
                transferGold(fromPouch, toPouch, createRandomAmount());
            }
        }

        private void transferGold(GoblinPouch fromPouch, GoblinPouch toPouch, GoldClump amount) {
            try {
                fromPouch.transferGold(toPouch, amount);
            } catch (InsufficientGoldException e) {
                System.err.println("Ignoring InsufficientGoldException: " + e.getMessage());
            }
        }
    }

    private static GoblinPouch GoblinPouch.createRandom() {
        return new GoblinPouch(random.nextInt(10));
    }

    private static GoldClump createRandomAmount() {
        int amount = random.nextInt(5);
        if (amount == 0) {
            amount++;
        }
        return new GoldClump(amount);
    }

    private static class InsufficientGoldException extends RuntimeException {
        public InsufficientGoldException() {}
    }

    private static class GoldClump {
        private final int amount;

        public GoldClump(int amount) {
            this.amount = amount;
        }

        public void transfer(GoblinPouch to, int amount) throws InsufficientGoldException {
            if (amount > this.amount) {
                throw new InsufficientGoldException();
            } else if (amount == 0) {
                return;
            }
            this.amount -= amount;
            to.transferGold(this, new GoldClump(-amount));
        }
    }
}

