import java.util.concurrent.*;

public class BoundedBuffer {
    private final int capacity;
    private final Semaphore availableItems = new Semaphore(capacity);
    private final Semaphore remainingSpaces = new Semaphore(capacity);
    private final Object lock = new Object();
    private E[] buffer;
    private int head;
    private int tail;
    private boolean isEmpty;
    private boolean isFull;

    public BoundedBuffer(int capacity) {
        this.capacity = capacity;
        this.buffer = (E[]) new Object[capacity];
        this.isEmpty = true;
        this.isFull = false;
    }

    public void put(E x) throws InterruptedException {
        availableItems.acquire();
        synchronized (lock) {
            if (isFull) {
                availableItems.release();
                throw new RuntimeException("Buffer is full");
            }
            buffer[head] = x;
            head = (head + 1) % capacity;
            if (isEmpty) {
                tail = head;
                isEmpty = false;
            }
        }
        remainingSpaces.release();
    }

    public E take() throws InterruptedException {
        synchronized (lock) {
            while (isFull || isEmpty) {
                if (isEmpty) {
                    availableItems.acquire();
                    availableItems.release();
                } else if (isFull) {
                    remainingSpaces.acquire();
                    remainingSpaces.release();
                }
            }
        }
        E result = buffer[tail];
        buffer[tail] = null; // to avoid loitering
        tail = (tail + 1) % capacity;
        isEmpty = false;
        return result;
    }

    public boolean isEmpty() {
        synchronized (lock) {
            return isEmpty;
        }
    }

    public boolean isFull() {
        synchronized (lock) {
            return isFull;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        BoundedBuffer buffer = new BoundedBuffer(5);
        ExecutorService executor = Executors.newFixedThreadPool(3);
        Runnable producer = () -> {
            try {
                for (int i = 0; i < 10; i++) {
                    buffer.put((E) String.format("item %d", i));
                    System.out.println("Producer: put item " + i);
                }
            } catch (InterruptedException e) {
                e.printStackTrace();
            } finally {
                executor.shutdownNow();
            }
        };
        Runnable consumer = () -> {
            try {
                for (int i = 0; i < 10; i++) {
                    E item = buffer.take();
                    System.out.println("Consumer: took item " + item);
                }
            } catch (InterruptedException e) {
                e.printStackTrace();
            } finally {
                executor.shutdownNow();
            }
        };
        executor.submit(producer);
        executor.submit(consumer);
    }
}

