public class BoundedBuffer {
    private final int CAPACITY;
    private final Semaphore availableItems; // Number of items remaining in buffer
    private final Semaphore freeSpaces; // Number of spaces remaining in buffer
    private final Object lock = new Object(); // Lock for synchronized block
    private final Queue<Object> queue; // Circular buffer

    public BoundedBuffer(int capacity) {
        this.CAPACITY = capacity;
        availableItems = new Semaphore(capacity);
        freeSpaces = new Semaphore(0);
        queue = new ConcurrentLinkedQueue<>();
    }

    // Put an item into the buffer
    public void put(Object x) {
        try {
            freeSpaces.acquire(); // Wait for a free space in the queue
            synchronized (lock) {
                queue.add(x); // Add item to the queue
                availableItems.release(); // Signal that an item has been added
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
    }

    // Remove and return an item from the buffer
    public Object take() {
        try {
            availableItems.acquire(); // Wait for available item in the queue
            synchronized (lock) {
                Object x = queue.poll(); // Remove and return first item from queue
                freeSpaces.release(); // Signal that an item has been removed
                return x;
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
    }

    // Check if the buffer is empty
    public boolean isEmpty() {
        synchronized (lock) {
            return queue.isEmpty();
        }
    }

    // Check if the buffer is full
    public boolean isFull() {
        synchronized (lock) {
            return queue.size() == CAPACITY;
        }
    }

    // Main entry point for concurrent program
    public static void main(String[] args) throws Exception {
        BoundedBuffer buffer = new BoundedBuffer(2); // Buffer capacity of 2 items

        Thread producer = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                buffer.put(i);
                if (buffer.isFull()) {
                    System.out.println("Producer: Buffer is full! Waiting for space to become available.");
                } else if (buffer.isEmpty()) {
                    System.out.println("Producer: Buffer is empty! Waiting for an item to become available.");
                }
            }
        });

        Thread consumer = new Thread(() -> {
            while (true) {
                Object x = buffer.take();
                if (x != null) {
                    System.out.println("Consumer: Received item " + x);
                } else if (buffer.isFull()) {
                    System.out.println("Consumer: Buffer is full! Waiting for space to become available.");
                } else if (buffer.isEmpty()) {
                    System.out.println("Consumer: Buffer is empty! Waiting for an item to become available.");
                }
            }
        });

        producer.start();
        consumer.start();

        // Wait for threads to finish or be interrupted
        try {
            producer.join();
            consumer.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
    }
}

