import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class Singleton {
    private static final String RESOURCES = "resources/";
    private static final int NUM_THREADS = 3; // maximum number of threads, including main thread
    private static volatile Singleton instance;

    // Lazily initialize the singleton resource on first access.
    private Singleton() {
        try {
            Thread.sleep(100); // simulate initialization delay
            System.out.println("Resource initialized with ID: " + Integer.toHexString(hashCode()));
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    // Thread-safe method to access the singleton instance.
    public static Singleton getInstance() {
        if (instance == null) {
            synchronized (Singleton.class) {
                if (instance == null) {
                    instance = new Singleton();
                }
            }
        }
        return instance;
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS - 1); // fixed thread pool size of maximum number of threads, including main thread
        for (int i = 0; i < NUM_THREADS; i++) {
