public class TreiberStack implements AutoCloseable {
    private static final int SIZE = 16;
    private AtomicReference<Node> top = new AtomicReference<>(null);
    private static class Node {
        final int item;
        volatile Node next;

        public Node(int item) {
            this.item = item;
        }
    }

    public synchronized boolean isEmpty() {
        return top == null;
    }

    public synchronized void push(int item) {
        while (true) {
            Node oldTop = top.get();
            Node newTop = new Node(item);
            if (top.compareAndSet(oldTop, newTop)) {
                return;
            } else if (oldTop == null || oldTop.next == null) {
                continue;
            }
        }
    }

    public synchronized int pop() {
        while (true) {
            Node oldTop = top.get();
            if (oldTop == null) {
                return Integer.MIN_VALUE;
            }
            Node newTop = oldTop.next;
            if (top.compareAndSet(oldTop, newTop)) {
                return oldTop.item;
            } else if (oldTop.next == null) {
                continue;
            }
        }
    }

    public synchronized int peek() {
        Node top = this.top.get();
        if (top != null && top.next != null) {
            return top.item;
        } else if (top == null || top.next == null) {
            return Integer.MIN_VALUE;
        }
    }

    @Override
    public synchronized void close() throws InterruptedException {
        while (true) {
            Node oldTop = top.get();
            if (oldTop != null && oldTop.next != null) {
                top.compareAndSet(oldTop, null);
                return;
            } else if (oldTop == null || oldTop.next == null) {
                continue;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(3);
        for (int i = 0; i < SIZE * 5; i++) {
            final int index = i;
            executor.submit(() -> {
                TreiberStack stack = new TreiberStack();
                for (int j = 0; j < 5; j++) {
                    stack.push(index + j);
                }
                for (int j = 0; j < 5; j++) {
                    int item = stack.pop();
                    if (item == Integer.MIN_VALUE) {
                        System.out.println("Stack is empty!");
                    } else {
                        System.out.println(index + " popped " + item);
                    }
                }
            });
        }
        executor.shutdown();
        while (!executor.isTerminated()) {}
        System.out.println("All tasks have finished.");
    }
}

