public class ConcurrentStack {
    private static final int THREAD_POOL_SIZE = 3; // fixed thread pool size
    private AtomicReference<Node> topRef = new AtomicReference<>(null);

    static class Node {
        final Object item;
        volatile Node next;

        public Node(Object item, Node next) {
            this.item = item;
            this.next = next;
        }
    }

    private static void push(Node newTop) {
        topRef.compareAndSet(null, newTop); // compare and set the top node
    }

    private static Node pop() {
        Node curr = topRef.get();
        while (curr != null && curr.next == null) {
            // loop if current is not removed yet
            topRef.compareAndSet(curr, null); // compare and set the top node
            return curr;
        }
        return curr.next; // return next node if current has a next element
    }

    public static void main(String[] args) throws InterruptedException {
        ThreadPoolExecutor executor = new ThreadPoolExecutor(0, THREAD_POOL_SIZE, 1, TimeUnit.SECONDS, new ArrayBlockingQueue<>(THREAD_POOL_SIZE)); // fixed thread pool

