import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;

public class VehicleLocation {
    private final double latitude;
    private final double longitude;

    public VehicleLocation(double latitude, double longitude) {
        this.latitude = latitude;
        this.longitude = longitude;
    }
}

public class DelegatingVehicleTracker {
    private final ConcurrentHashMap<String, Supplier<VehicleLocation>> vehicleLocations;

    public DelegatingVehicleTracker(ConcurrentHashMap<String, Supplier<VehicleLocation>> initialVehicleLocations) {
        this.vehicleLocations = new ConcurrentHashMap<>(initialVehicleLocations);
    }

    public VehicleLocation getLocation(String vehicleId) {
        return vehicleLocations.getOrDefault(vehicleId, () -> null).get();
    }

    public boolean setLocation(String vehicleId, double latitude, double longitude) {
        if (!vehicleLocations.containsKey(vehicleId)) {
            return false;
        }

        Supplier<VehicleLocation> locationSupplier = () -> new VehicleLocation(latitude, longitude);
        boolean updated = vehicleLocations.replace(vehicleId, () -> null, locationSupplier) == null;
        return updated;
    }

    public ConcurrentHashMap<String, VehicleLocation> getLiveLocations() {
        return new UnmodifiableVehicleLocationsView(vehicleLocations);
    }

    public ConcurrentHashMap<String, VehicleLocation> snapshotCurrentState() {
        return new UnmodifiableVehicleLocationsView(new CurrentStateSnapshotter(vehicleLocations));
    }

    private static class UnmodifiableVehicleLocationsView extends UnmodifiableMapWrapper<String, VehicleLocation> {
        public UnmodifiableVehicleLocationsView(ConcurrentHashMap<String, Supplier<VehicleLocation>> map) {
            super(map);
        }
    }

    private static class CurrentStateSnapshotter implements Supplier<ConcurrentHashMap<String, VehicleLocation>> {
        private final ConcurrentHashMap<String, Supplier<VehicleLocation>> snapshot;

        public CurrentStateSnapshotter(ConcurrentHashMap<String, Supplier<VehicleLocation>> original) {
            this.snapshot = new ConcurrentHashMap<>(original);
        }

        @Override
        public ConcurrentHashMap<String, VehicleLocation> get() {
