import java.util.*;
import java.util.concurrent.*;

public class ArkLoader {
    private static final int THREADS = 3; // Total number of threads, including the main thread
    private static final ExecutorService executor = new ThreadPoolExecutor(0, THREADS,
            60L, TimeUnit.SECONDS, new ArrayBlockingQueue<>(10));
    private static final Random random = new Random();

    // Enums representing animal species and gender
    public enum AnimalSpecies {MALE, FEMALE}
    public enum Gender {MALE, FEMALE}

    // Class to represent each animal
    public class Animal implements Comparable<Animal> {
        private final String name;
        private final AnimalSpecies species;
        private final Gender gender;

        public Animal(String name, AnimalSpecies species, Gender gender) {
            this.name = name;
            this.species = species;
            this.gender = gender;
        }

        @Override
        public int compareTo(Animal other) {
            int result = species.ordinal() - other.species.ordinal();
            if (result == 0) {
                result = gender.ordinal() - other.gender.ordinal();
            }
            return result;
        }
    }

    // Class to represent each animal pair
    public class AnimalPair {
        private final Animal male;
        private final Animal female;

        public AnimalPair(Animal male, Animal female) {
            this.male = male;
            this.female = female;
        }
    }

    // Method to load animals onto the ark
    public int loadTheArk(Collection<Animal> candidates) {
        List<AnimalPair> pairs = new ArrayList<>();
        Map<Gender, List<Animal>> groupedCandidates = groupByGender(candidates);

        // Sort animals by species and gender
        List<Animal> sortedMales = new ArrayList<>(groupedCandidates.get(Gender.MALE));
        sortedMales.sort(null);
        List<Animal> sortedFemales = new ArrayList<>(groupedCandidates.get(Gender.FEMALE));
        sortedFemales.sort(null);

        // Create two additional threads to process males and females separately
        Callable<List<AnimalPair>> maleTask = () -> processMales(sortedMales, genderFilter(Gender.MALE), pairs);
        Callable<List<AnimalPair>> femaleTask = () -> processFemales(sortedFemales, genderFilter(Gender.FEMALE), pairs);
        executor.submit(maleTask);
        executor.submit(femaleTask);

        try {
            return (int) executor.invokeAny(new ArrayList<>(Arrays.asList(maleTask, femaleTask)));
        } finally {
            executor.shutdown();
        }
    }

    private List<Animal> genderFilter(Gender filter) {
        List<Animal> filteredCandidates = new ArrayList<>();
        for (Animal candidate : candidates) {
            if (candidate.gender == filter) {
                filteredCandidates.add(candidate);
            }
        }
        return filteredCandidates;
    }

    private List<List<Animal>> groupByGender(Collection<Animal> animals) {
        Map<Gender, List<Animal>> groupedAnimals = new HashMap<>();
        for (Animal animal : animals) {
            groupedAnimals.computeIfAbsent(animal.gender, k -> new ArrayList<>()).add(animal);
        }
        return new ArrayList<>(groupedAnimals.values());
    }

    private List<AnimalPair> processMales(List<Animal> males, Collection<Gender> filterGenders, List<AnimalPair> pairs) {
        for (int i = 0; i < males.size(); i++) {
            if (random.nextInt(males.size() / 2) == 0) { // Minimal loop iteration count
                for (Animal female : filterGenders) {
                    if (!pairs.contains(new AnimalPair(males.get(i), female))) {
                        pairs.add(new AnimalPair(males.get(i), female));
                    }
                }
            }
        }
        return pairs;
    }

    private List<AnimalPair> processFemales(List<Animal> females, Collection<Gender> filterGenders, List<AnimalPair> pairs) {
        for (int i = 0; i < females.size(); i++) {
            if (random.nextInt(females.size() / 2) == 0) { // Minimal loop iteration count
                for (Gender male : filterGenders) {
                    if (!pairs.contains(new AnimalPair(females.get(i), new Animal(null, male)))) {
                        pairs.add(new AnimalPair(females.get(i), new Animal(null, male)));
                    }
                }
            }
        }
        return pairs;
    }

    // Main method as the entry point
    public static void main(String[] args) {
        List<Animal> animals = Arrays.asList(new Animal("Lion", Gender.MALE, Gender.FEMALE), new Animal("Zebra", Gender.MALE, Gender.FEMALE),
                new Animal("Tiger", Gender.MALE, Gender.FEMALE), new Animal("Elephant", Gender.MALE, Gender.FEMALE),
                new Animal("Giraffe", Gender.FEMALE, Gender.MALE), new Animal("Hippopotamus", Gender.FEMALE, Gender.MALE));
        int pairsLoaded = new ArkLoader().loadTheArk(animals);
        System.out.println("Number of valid animal pairs loaded onto the ark: " + pairsLoaded);
    }
}

