public class AnimalPairingProgram {
    enum Gender {MALE, FEMALE}

    class Ark {
        List<AnimalPair> pairs = new ArrayList<>();

        void addPair(AnimalPair pair) {
            pairs.add(pair);
        }

        int numPairs() {
            return pairs.size();
        }
    }

    class AnimalPair {
        Animal male;
