        public AnimalPair(Animal male, Animal female) {
            this.male = male;
            this.female = female;
        }
    }

    class Animal {
        Gender gender;
        String species;

        public Animal(Gender gender, String species) {
            this.gender = gender;
            this.species = species;
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof Animal)) {
                return false;
            }
            Animal other = (Animal) obj;
            return this.species.equals(other.species) && this.gender == other.gender;
        }
    }

    class PairingComparator implements Comparator<Animal> {
        @Override
        public int compare(Animal a, Animal b) {
            int result = a.species.compareTo(b.species);
            if (result == 0) {
                result = a.gender.ordinal() - b.gender.ordinal();
            }
            return result;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        int numAnimals = 3; // number of animals to simulate
        Collection<Animal> candidates = generateCandidates(numAnimals);

        List<Runnable> tasks = new ArrayList<>(numAnimals / 2);
        for (Animal a : candidates) {
            tasks.add(() -> pairAnimals(a, candidates));
        }
        executor.invokeAll(tasks);
        executor.shutdown();
    }

    private static Collection<Animal> generateCandidates(int numAnimals) {
        List<Animal> animals = new ArrayList<>(numAnimals);
        Gender[] genders = Gender.values();
        for (int i = 0; i < numAnimals / 2; i++) {
            animals.add(new Animal(genders[i % 2], "species" + i));
            animals.add(new Animal(genders[(i * 3) % 4], "species" + (i * 3)));
        }
        return animals;
    }

    private static void pairAnimals(final Animal animal, final Collection<Animal> candidates) {
        List<AnimalPair> pairs = new ArrayList<>();
        for (Animal candidate : candidates) {
            if (!candidate.equals(animal)) {
                if (compatibleGenders(animal, candidate)) {
                    pairs.add(new AnimalPair(animal, candidate));
                }
            }
        }
        System.out.println("Formed " + pairs.size() + " valid animal pair(s) with " + animal);
    }

    private static boolean compatibleGenders(Animal a, Animal b) {
        return (a.gender == Gender.MALE && b.gender == Gender.FEMALE) ||
                (a.gender == Gender.FEMALE && b.gender == Gender.MALE);
    }
}

