class LoadTheArk implements Runnable {
    private final List<Animal> animals;
    private final ExecutorService executor;
    private final Ark ark;

    LoadTheArk(List<Animal> animals, ExecutorService executor, Ark ark) {
        this.animals = animals;
        this.executor = executor;
        this.ark = ark;
    }

    @Override
    public void run() {
        try (Comparator<Animal> comparator = Comparator.comparingInt(a -> a.getSpeciesId())
                .thenComparing(a -> a.getGender().equals(Gender.MALE) ? -1 : 1)) {
            List<PairBuilderTask> tasks = new ArrayList<>(animals.size());
            for (int i = 0; i < animals.size(); i++) {
                Animal animal = animals.get(i);
                tasks.add(new PairBuilderTask(animal, comparator));
            }
            executor.invokeAll(tasks);
        } finally {
            executor.shutdownNow();
        }
    }

    private class PairBuilderTask implements Runnable {
        private final Animal animal;
        private final Comparator<Animal> comparator;

        PairBuilderTask(Animal animal, Comparator<Animal> comparator) {
            this.animal = animal;
            this.comparator = comparator;
        }

        @Override
        public void run() {
            List<AnimalPair> validPairs = new ArrayList<>();
            for (int i = 0; i < animals.size(); i++) {
                if (i == animal.compareTo(animals.get(i), comparator)) {
                    continue;
                }
                Animal other = animals.get(comparator.compare(animal, animals.get(i)) > 0 ? i : -i);
                if (!animal.getGender().equals(other.getGender())) {
                    validPairs.add(new AnimalPair(animal, other));
                }
            }
            ark.addPair(animals.size() == 0 || animals.isEmpty() ? null : validPairs);
        }
    }
}

