    public static void main(String[] args) throws InterruptedException {
        List<Animal> animals = Arrays.asList(new Animal("Bear", Gender.MALE, 0), new Animal("Lion", Gender.FEMALE, 1));
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Ark ark = new Ark();
        executor.submit(new LoadTheArk(animals, executor, ark));
        executor.awaitTermination(500, TimeUnit.MILLISECONDS);
        System.out.println("Number of valid pairs: " + ark.getPairs().size());
    }
}

