public class PrimeProducer implements Runnable {
    private final BlockingQueue<Integer> queue;
    private int numPrimesToGenerate;

    public PrimeProducer(BlockingQueue<Integer> queue, int numPrimesToGenerate) {
        this.queue = queue;
        this.numPrimesToGenerate = numPrimesToGenerate;
    }

    @Override
    public void run() {
        try {
            for (int i = 2; i <= numPrimesToGenerate; i++) {
                if (isPrime(i)) {
                    queue.put(i);
                } else {
                    Thread.sleep((long) Math.pow(10, i)); // Sleep for increasing amounts of time on each non-prime
                }
            }
        } catch (InterruptedException | InterruptedIOException e) {
            // Cleanly exit the thread when interrupted
            System.out.println("Producer stopped: " + Thread.currentThread().getName());
            Thread.currentThread().interrupt();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            System.out.println("Producer finished generating primes: " + queue.isEmpty());
        }
    }

    private boolean isPrime(int num) {
        for (int i = 2; i < Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

