        Thread producerThread = new PrimeProducer(queue, "producer");
        Thread consumerThread = new PrimeConsumer(queue, "consumer");

        ExecutorService executor = Executors.newFixedThreadPool(2, new NamedThreadFactory());
        executor.submit(producerThread);
        executor.submit(consumerThread);
        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    }

    private static class NamedThreadFactory implements ThreadFactory {
        private final AtomicBoolean createdFirstThread = new AtomicBoolean(false);
        private final String namePrefix;

        public NamedThreadFactory() {
            namePrefix = "named-thread-";
        }

        @Override
        public Thread newThread(Runnable r) {
            Thread t = new Thread(r, namePrefix + createdFirstThread.getAndSet(true));
            t.setDaemon(false);
            return t;
        }
    }

    private static class PrimeProducer extends Thread implements Runnable {
        private final BlockingQueue<Integer> queue;
        private final String name;
        private boolean interrupted = false;
        private AtomicBoolean terminated = new AtomicBoolean(false);

        public PrimeProducer(BlockingQueue<Integer> queue, String name) {
            super(name);
            this.queue = queue;
            this.name = name;
        }

        @Override
        public void run() {
            if (DEBUG) {
                System.out.println(name + " started");
            }
            try {
                generatePrimes();
            } catch (InterruptedException e) {
                interrupted = true;
                terminated.set(true);
            } finally {
                if (DEBUG) {
                    System.out.println(name + " finished");
                }
                queue.notify();
            }
        }

        private void generatePrimes() throws InterruptedException {
            boolean isPrime = true;
            for (int i = 2, j = 3; j <= NUM_TARGET_PRIMES && !interrupted; i++, j += 2) {
                if (isPrime(i)) {
                    queue.put(i);
                }
            }
        }

        private boolean isPrime(int n) {
            for (int i = 2; i <= Math.sqrt(n); i++) {
                if (n % i == 0) {
                    return false;
                }
            }
            return true;
        }

        @Override
        public void interrupt() {
            super.interrupt();
            interrupted = true;
        }
    }

    private static class PrimeConsumer extends Thread implements Runnable {
        private final BlockingQueue<Integer> queue;
        private final String name;
        private boolean interrupted = false;
        private AtomicBoolean terminated = new AtomicBoolean(false);

        public PrimeConsumer(BlockingQueue<Integer> queue, String name) {
