    public String compute() throws InterruptedException, ExecutionException {
        List<String> results = new ArrayList<>();
        for (Future<String> future : futures) {
            results.add(future.get());
        }
        executor.shutdown();
        return String.join("", results);
    }
}

class NodeProcessor implements Element {
    private final Node node;

    public NodeProcessor(Node node) {
        this.node = node;
    }

    @Override
    public String compute() {
        return new SequentialProcessor(node.getChildren()).compute();
    }
}

class ParallelNodeProcessor implements Element {
    private final ExecutorService executor = newFixedThreadPool(2);
    private final List<Future<String>> futures;

    public ParallelNodeProcessor(Node node) {
        this.futures = new ArrayList<>();
        for (Element child : node.getChildren()) {
            futures.add(executor.submit(() -> ((NodeProcessor) child).compute()));
        }
    }

    @Override
    public String compute() throws InterruptedException, ExecutionException {
        List<String> results = new ArrayList<>();
        for (Future<String> future : futures) {
            results.add(future.get());
        }
        executor.shutdown();
        return new SequentialProcessor(node.getChildren()).compute();
    }
}

public class ConcurrentProcessing {
    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Node root = new Node(Arrays.asList(
            new Element() {
                @Override
                public String compute() {
                    return "a";
                }
            },
            new NodeProcessor(new Node(Arrays.asList(
                new Element() {
                    @Override
                    public String compute() {
                        return "b";
                    }
                },
                new Element() {
                    @Override
                    public String compute() {
                        return "c";
                    }
                })))
        ));

        System.out.println(new SequentialProcessor(root).compute());
        System.out.println(new ParallelNodeProcessor(root).compute());
    }
}

