import java.util.*;
import java.util.concurrent.locks.*;

public class ReadWriteMap {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> m) {
        map = Collections.unmodifiableMap(m);
    }

    public List<V> getAllValues() {
        List<V> values = new ArrayList<>(map.values());
        return values;
    }

    public void putIfAbsent(K key, V value) {
        try (Lock readLock = rwLock.readLock()) {
            if (!map.containsKey(key)) {
                try (Lock writeLock = rwLock.writeLock()) {
                    map.put(key, value);
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
    }

    public void runMultipleTasksConcurrently(int numTasks) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(numTasks - 1);
        for (int i = 0; i < numTasks; i++) {
            final int taskId = i;
            executor.submit(() -> {
                try (Lock readLock = rwLock.readLock()) {
                    if (taskId % 2 == 1) {
                        putIfAbsent("key" + taskId, "value" + taskId);
                    } else {
                        List<V> values = getAllValues();
                        values.forEach((v) -> System.out.println(v));
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException(e);
                }
            });
        }
        executor.shutdown();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Map<String, Integer> map = new HashMap<>();
        map.put("one", 1);
        map.put("two", 2);
        ReadWriteMap rwMap = new ReadWriteMap(map);

        Thread taskRunner = new Thread(() -> {
            try {
                rwMap.runMultipleTasksConcurrently(4);
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        });

        taskRunner.start();
    }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

public class ReadWriteMap {
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private final Lock readLock = lock.readLock();
    private final Lock writeLock = lock.writeLock();
    private final Map<K, V> map;

    public ReadWriteMap(Map<K, V> m) {
        map = new HashMap<>(m);
    }

    public synchronized void put(K key, V value) {
        writeLock.lock();
        try {
            map.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public synchronized V get(Object key) {
        readLock.lock();
        try {
            return map.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public synchronized void remove(Object key, Object value) {
        writeLock.lock();
        try {
            map.remove(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    // Add more methods as needed (putAll, clear, etc.)

    public static void main(String[] args) throws InterruptedException {
        Map<Integer, String> map = new HashMap<>();
        for (int i = 0; i < 1000; i++) {
            map.put(i, "Value" + i);
        }
        ReadWriteMap readWriteMap = new ReadWriteMap(map);
        ExecutorService executor = Executors.newFixedThreadPool(3);

        for (int i = 1; i <= 500; i++) {
            executor.submit(() -> {
                try {
                    readWriteMap.get(i);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            });
        }

        for (int i = 1; i <= 200; i++) {
            executor.submit(() -> {
                try {
                    readWriteMap.put(i, "New Value" + i);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);
        System.out.println("ReadWriteMap processed!");
    }
}

import java.util.*;
