public class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock rwlock = new ReentrantReadWriteLock();
    private final Lock readLock = rwlock.readLock();
    private final Lock writeLock = rwlock.writeLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    // Write operations require a lock to be held by the thread executing them
    public void put(K key, V value) {
        writeLock.lock();
        try {
            map.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public boolean remove(Object key, Object value) {
        writeLock.lock();
        try {
            return map.remove(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        writeLock.lock();
        try {
            map.putAll(m);
        } finally {
            writeLock.unlock();
        }
    }

    public void clear() {
        writeLock.lock();
        try {
            map.clear();
        } finally {
            writeLock.unlock();
        }
    }

    // Read operations do not require any locks to be held by the thread executing them, but they may block if other threads are holding write locks or if there is contention for read locks
    public V get(Object key) {
        readLock.lock();
        try {
            return map.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public int size() {
        readLock.lock();
        try {
            return map.size();
        } finally {
            readLock.unlock();
        }
    }

    public boolean isEmpty() {
        readLock.lock();
        try {
            return map.isEmpty();
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsKey(Object key) {
        readLock.lock();
        try {
            return map.containsKey(key);
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsValue(Object value) {
        readLock.lock();
        try {
            return map.containsValue(value);
        } finally {
            readLock.unlock();
        }
    }

    // Example usage:
    // ReadWriteMap<String, Integer> m = new ReadWriteMap<>(new HashMap<>());
    // ...
    public static void main(String[] args) throws InterruptedException {
        ReadWriteMap<String, Integer> map = new ReadWriteMap<>(new HashMap<>());
        ExecutorService executor = Executors.newFixedThreadPool(3); // use a fixed thread pool with up to 3 threads beyond the main thread

        // add some data to the map
        executor.submit(() -> {
            for (int i = 0; i < 2; i++) {
                map.put("key" + i, 100 * i);
            }
        });

        // try to get values concurrently
        executor.submit(() -> {
            int count = 0;
            while (count++ < 2) {
                System.out.println(map.get("key" + ThreadLocalRandom.current().nextInt(2)));
            }
        });

        // try to update data concurrently
        executor.submit(() -> {
            while (true) {
                try {
                    map.put(ThreadLocalRandom.current().nextDouble() + "", ThreadLocalRandom.current().nextInt());
                } catch (Exception e) {
                    // ignore
                }
            }
        });

        executor.shutdown(); // wait for tasks to complete and then shut down the executor
    }
}

